925    ft_var_load_gvar( TT_Face  face )
   926    {
   927      FT_Stream     stream = FT_FACE_STREAM( face );
   928      FT_Memory     memory = stream->memory;
   929      GX_Blend      blend  = face->blend;
   930      FT_Error      error;
   931      FT_UInt       i, j;
   932      FT_ULong      table_len;
   933      FT_ULong      gvar_start;
   934      FT_ULong      offsetToData;
   935      GX_GVar_Head  gvar_head;
   936
   937      static const FT_Frame_Field  gvar_fields[] =
   938      {
   939
   940  #undef  FT_STRUCTURE
   941  #define FT_STRUCTURE  GX_GVar_Head
   942
   943        FT_FRAME_START( 20 ),
   944          FT_FRAME_LONG  ( version ),
   945          FT_FRAME_USHORT( axisCount ),
   946          FT_FRAME_USHORT( globalCoordCount ),
   947          FT_FRAME_ULONG ( offsetToCoord ),
   948          FT_FRAME_USHORT( glyphCount ),
   949          FT_FRAME_USHORT( flags ),
   950          FT_FRAME_ULONG ( offsetToData ),
   951        FT_FRAME_END
   952      };
   953
   954
   955      FT_TRACE2(( "GVAR " ));
   956
   957      if ( ( error = face->goto_table( face,
   958                                       TTAG_gvar,
   959                                       stream,
   960                                       &table_len ) ) != 0 )
   961      {
   962        FT_TRACE2(( "is missing\n" ));
   963        goto Exit;
   964      }
   965
   966      gvar_start = FT_STREAM_POS( );
   967      if ( FT_STREAM_READ_FIELDS( gvar_fields, &gvar_head ) )
   968        goto Exit;
   969
   970      if ( gvar_head.version != 0x00010000L )
   971      {
   972        FT_TRACE1(( "bad table version\n" ));
   973        error = FT_THROW( Invalid_Table );
   974        goto Exit;
   975      }
   976
   977      if ( gvar_head.axisCount != (FT_UShort)blend->mmvar->num_axis )
   978      {
   979        FT_TRACE1(( "ft_var_load_gvar: number of axes in `gvar' and `cvar'\n"
   980                    "                  table are different\n" ));
   981        error = FT_THROW( Invalid_Table );
   982        goto Exit;
   983      }
   984
   985      /* rough sanity check, ignoring offsets */
   986      if ( (FT_ULong)gvar_head.globalCoordCount * gvar_head.axisCount >
   987             table_len / 2 )
   988      {
   989        FT_TRACE1(( "ft_var_load_gvar:"
   990                    " invalid number of global coordinates\n" ));
   991        error = FT_THROW( Invalid_Table );
   992        goto Exit;
   993      }
   994
   995      /* rough sanity check: offsets can be either 2 or 4 bytes, */
   996      /* and a single variation needs at least 4 bytes per glyph */
   997      if ( (FT_ULong)gvar_head.glyphCount *
   998             ( ( gvar_head.flags & 1 ) ? 8 : 6 ) > table_len )
   999      {
  1000        FT_TRACE1(( "ft_var_load_gvar: invalid number of glyphs\n" ));
  1001        error = FT_THROW( Invalid_Table );
  1002        goto Exit;
  1003      }
  1004
  1005      FT_TRACE2(( "loaded\n" ));
  1006
  1007      blend->gvar_size   = table_len;
  1008      blend->tuplecount  = gvar_head.globalCoordCount;
  1009      blend->gv_glyphcnt = gvar_head.glyphCount;
  1010      offsetToData       = gvar_start + gvar_head.offsetToData;
  1011
  1012      FT_TRACE5(( "gvar: there are %d shared coordinates:\n",
  1013                  blend->tuplecount ));
  1014
  1015      if ( FT_NEW_ARRAY( blend->glyphoffsets, blend->gv_glyphcnt + 1 ) )
  1016        goto Exit;
  1017
  1018      if ( gvar_head.flags & 1 )
  1019      {
  1020        /* long offsets (one more offset than glyphs, to mark size of last) */
  1021        if ( FT_FRAME_ENTER( ( blend->gv_glyphcnt + 1 ) * 4L ) )
  1022          goto Exit;
  1023
  1024        for ( i = 0; i <= blend->gv_glyphcnt; i++ )
  1025          blend->glyphoffsets[i] = offsetToData + FT_GET_ULONG();
  1026
  1027        FT_FRAME_EXIT();
  1028      }
  1029      else
  1030      {
  1031        /* short offsets (one more offset than glyphs, to mark size of last) */
  1032        if ( FT_FRAME_ENTER( ( blend->gv_glyphcnt + 1 ) * 2L ) )
  1033          goto Exit;
  1034
  1035        for ( i = 0; i <= blend->gv_glyphcnt; i++ )
  1036          blend->glyphoffsets[i] = offsetToData + FT_GET_USHORT() * 2;
  1037                                                 /* XXX: Undocumented: `*2'! */
  1038
  1039        FT_FRAME_EXIT();
  1040      }
  1041
  1042      if ( blend->tuplecount != 0 )
  1043      {
  1044        if ( FT_NEW_ARRAY( blend->tuplecoords,
  1045                           gvar_head.axisCount * blend->tuplecount ) )
  1046          goto Exit;
  1047
  1048        if ( FT_STREAM_SEEK( gvar_start + gvar_head.offsetToCoord )         ||
  1049             FT_FRAME_ENTER( blend->tuplecount * gvar_head.axisCount * 2L ) )
  1050          goto Exit;
  1051
  1052        for ( i = 0; i < blend->tuplecount; i++ )
  1053        {
  1054          FT_TRACE5(( "  [ " ));
  1055          for ( j = 0; j < (FT_UInt)gvar_head.axisCount; j++ )
  1056          {
  1057            blend->tuplecoords[i * gvar_head.axisCount + j] =
  1058              FT_GET_SHORT() * 4;                 /* convert to FT_Fixed */
  1059            FT_TRACE5(( "%.4f ",
  1060              blend->tuplecoords[i * gvar_head.axisCount + j] / 65536.0 ));
  1061          }
  1062          FT_TRACE5(( "]\n" ));
  1063        }
  1064
  1065        FT_TRACE5(( "\n" ));
  1066
  1067        FT_FRAME_EXIT();
  1068      }
  1069
  1070    Exit:
  1071      return error;
  1072    }
  1073
  1074
  1075    /*************************************************************************/
  1076    /*                                                                       */
  1077    /* <Function>                                                            */
  1078    /*    ft_var_apply_tuple                                                 */
  1079    /*                                                                       */
  1080    /* <Description>                                                         */
  1081    /*    Figure out whether a given tuple (design) applies to the current   */
  1082    /*    blend, and if so, what is the scaling factor.                      */
  1083    /*                                                                       */
  1084    /* <Input>                                                               */
  1085    /*    blend           :: The current blend of the font.                  */
